// -- CBA generic prefix ---------------------------------------------------
// Fallback for any CBA_* / CBA.* name that isn't in the alias table above.
ArmADocs.addRoute({
    match: name => /^cba[_.]/i.test(name),
    url:   name => "https://cbateam.github.io/CBA_A3/docs/index/Functions.html#" + encodeURIComponent(name),
    label: "CBA docs"
});

// -- Fallback: Bohemia Interactive community wiki --------------------------
ArmADocs.setDefaultRoute({
    match: () => true,
    url:   name => "https://community.bistudio.com/wiki/" + encodeURIComponent(name),
    label: "Bohemia Interactive Wiki"
});
